    }

public Duration negated() {
        if (getMillis() == Long.MIN_VALUE) {
            throw new ArithmeticException("Negation of this duration would overflow");
        }
        return new Duration(-getMillis());
    }

public Duration abs() {
        if (getMillis() < 0) {
            return negated();
        }
        return this;
    }

