public String print(ReadablePeriod period) {
        checkPrinter();
        checkPeriod(period);

        PeriodPrinter printer = getPrinter();
        StringBuffer buf = new StringBuffer(printer.calculatePrintedLength(period, iLocale));
        printer.printTo(buf, period, iLocale);
        return buf.toString();
